-- Generated by Claude Code — Kalender-Abo der gemerkten Konzerte.
-- Pro Konto ein geheimes, nicht erratbares Token; der Kalender des Geräts
-- ruft damit /api/calendar/<token>.ics ab (admin-App, Service-Client).
create table if not exists calendar_feeds (
  user_id uuid primary key references auth.users(id) on delete cascade,
  token text not null unique default replace(gen_random_uuid()::text || gen_random_uuid()::text, '-', ''),
  created_at timestamptz not null default now()
);
alter table calendar_feeds enable row level security;
create policy "Nutzer sieht eigenes Kalender-Abo" on calendar_feeds for select using (user_id = auth.uid());

create or replace function my_calendar_feed_token()
returns text
language plpgsql
security definer
set search_path = public
as $$
declare
  v_token text;
begin
  if auth.uid() is null then raise exception 'Nicht angemeldet.'; end if;
  insert into calendar_feeds (user_id) values (auth.uid()) on conflict (user_id) do nothing;
  select token into v_token from calendar_feeds where user_id = auth.uid();
  return v_token;
end;
$$;

revoke all on function my_calendar_feed_token() from public, anon;
grant execute on function my_calendar_feed_token() to authenticated;
